"""Complete 8-pair 6-method analysis for Pythia-1B C4 experiment.

8 pairs: {token_entropy, ece} x {distinct_1, distinct_2, distinct_3, mauve}
6 methods: Naive XCorr, Diff XCorr, Threshold Onset, PermG forward, PermG reverse, TY Granger
"""

import json
import os
import sys
import warnings
import numpy as np
from statsmodels.stats.multitest import multipletests
from statsmodels.tsa.stattools import adfuller

warnings.filterwarnings("ignore")

BASE_DIR = "/root/autodl-tmp/distrib_canary_collapse"
sys.path.insert(0, BASE_DIR)
from permutation_granger import permutation_granger_test

DATA_PATH = os.path.join(BASE_DIR, "results", "generalize",
                         "pythia1b_c4_a100_s42", "all_metrics.json")
OUT_DIR = os.path.join(BASE_DIR, "results", "generalize",
                       "pythia1b_c4_a100_s42", "analysis")

CANARY = ["token_entropy", "ece"]
DOWNSTREAM = ["distinct_1", "distinct_2", "distinct_3", "mauve"]

HIGHER_IS_WORSE = {"self_bleu", "ece", "perplexity"}
LOWER_IS_WORSE = {"token_entropy", "effective_rank",
                  "distinct_1", "distinct_2", "distinct_3", "mauve"}

MAX_LAG = 1
N_PERM = 1000
SEED = 42
FDR_Q = 0.05


def orient(series, name):
    return -series.copy() if name in LOWER_IS_WORSE else series.copy()


def extract(metrics_list, name):
    return np.array([m[name] for m in sorted(metrics_list,
                                              key=lambda x: x["generation"])])


def _onset_gen(series, name):
    s = orient(series, name)
    base, sigma = s[0], np.std(s)
    if sigma < 1e-12:
        return None
    thresh = base + 2 * sigma
    for i in range(1, len(s)):
        if s[i] > thresh:
            return i
    return None


def _adf_order(series, max_d=2):
    for d in range(max_d + 1):
        s = series.copy()
        for _ in range(d):
            s = np.diff(s)
        if len(s) < 5:
            return d
        try:
            if adfuller(s, maxlag=1, autolag=None)[1] < 0.05:
                return d
        except Exception:
            pass
    return max_d


def naive_pearson(c, d, cn, dn, max_lag=3):
    xo, yo = orient(c, cn), orient(d, dn)
    best_r, best_lag, best_p = 0.0, 0, 1.0
    for lag in range(-max_lag, max_lag + 1):
        if lag > 0:
            xx, yy = xo[:-lag], yo[lag:]
        elif lag < 0:
            xx, yy = xo[-lag:], yo[:lag]
        else:
            xx, yy = xo, yo
        if len(xx) < 4:
            continue
        r, p = stats_pearsonr(xx, yy)
        if abs(r) > abs(best_r):
            best_r, best_lag, best_p = r, lag, p
    return {
        "method": "naive_pearson",
        "r": float(best_r), "lag": int(best_lag),
        "p_value": float(best_p),
        "significant": bool(best_p < 0.05 and best_lag > 0),
    }


def diff_xcorr(c, d, cn, dn, max_lag=3):
    xo, yo = orient(c, cn), orient(d, dn)
    dx, dy = np.diff(xo), np.diff(yo)
    best_r, best_lag, best_p = 0.0, 0, 1.0
    for lag in range(-max_lag, max_lag + 1):
        if lag > 0:
            xx, yy = dx[:-lag], dy[lag:]
        elif lag < 0:
            xx, yy = dx[-lag:], dy[:lag]
        else:
            xx, yy = dx, dy
        if len(xx) < 4:
            continue
        r, p = stats_pearsonr(xx, yy)
        if abs(r) > abs(best_r):
            best_r, best_lag, best_p = r, lag, p
    return {
        "method": "differenced_xcorr",
        "r": float(best_r), "lag": int(best_lag),
        "p_value": float(best_p),
        "significant": bool(best_p < 0.05),
    }


def threshold_lead(c, d, cn, dn):
    co = _onset_gen(c, cn)
    do = _onset_gen(d, dn)
    if co is None or do is None:
        return {
            "method": "threshold_onset",
            "canary_onset": None if co is None else int(co),
            "downstream_onset": None if do is None else int(do),
            "lead_time": None,
            "significant": False,
        }
    lt = do - co
    return {
        "method": "threshold_onset",
        "canary_onset": int(co),
        "downstream_onset": int(do),
        "lead_time": int(lt),
        "significant": bool(lt > 0),
    }


def toda_yamamoto(c, d, cn, dn):
    x, y = orient(c, cn), orient(d, dn)
    n = len(x)
    dc, dd = _adf_order(x), _adf_order(y)
    d_max = max(dc, dd)
    p = 1
    k = p + d_max
    T_eff = n - k
    n_params = 1 + 2 * k
    df_resid = T_eff - n_params

    if df_resid < 1:
        return {
            "method": "toda_yamamoto", "p": p, "d_max": d_max,
            "wald_F": None, "p_value": None, "significant": False,
            "note": f"no residual df (T_eff={T_eff}, params={n_params})",
            "d_canary": dc, "d_downstream": dd,
        }

    Y = y[k:]
    X_cols = [np.ones(T_eff)]
    for l in range(1, k + 1):
        X_cols.append(x[k - l : n - l])
        X_cols.append(y[k - l : n - l])
    X = np.column_stack(X_cols)

    try:
        beta = np.linalg.lstsq(X, Y, rcond=None)[0]
        resid = Y - X @ beta
        sigma2 = np.sum(resid ** 2) / df_resid
        XtX_inv = np.linalg.inv(X.T @ X)
    except Exception:
        return {
            "method": "toda_yamamoto", "p": p, "d_max": d_max,
            "wald_F": None, "p_value": None, "significant": False,
            "note": "OLS failed",
            "d_canary": dc, "d_downstream": dd,
        }

    test_idx = [2 * (l - 1) + 1 for l in range(1, p + 1)]
    R = np.zeros((p, n_params))
    for i, idx in enumerate(test_idx):
        R[i, idx] = 1.0
    Rb = R @ beta
    try:
        mid = R @ XtX_inv @ R.T * sigma2
        mid_inv = np.linalg.inv(mid)
    except Exception:
        return {
            "method": "toda_yamamoto", "p": p, "d_max": d_max,
            "wald_F": None, "p_value": None, "significant": False,
            "note": "Wald matrix singular",
            "d_canary": dc, "d_downstream": dd,
        }

    wald = float(Rb @ mid_inv @ Rb / p)
    from scipy import stats as sp_stats
    p_val = float(1 - sp_stats.f.cdf(wald, p, df_resid))
    return {
        "method": "toda_yamamoto", "p": p, "d_max": d_max,
        "wald_F": round(wald, 4), "p_value": round(p_val, 6),
        "significant": bool(p_val < 0.05),
        "d_canary": dc, "d_downstream": dd, "df_resid": df_resid,
    }


def perm_granger_fwd(c, d, cn, dn):
    xo, yo = orient(c, cn), orient(d, dn)
    res = permutation_granger_test(xo, yo, max_lag=MAX_LAG,
                                   n_perm=N_PERM, seed=SEED, difference=True)
    return {
        "method": "perm_granger_fwd",
        "f_stat": round(float(res["f_stat"]), 4),
        "p_value": round(float(res["p_value"]), 4),
        "significant": bool(res["significant"]),
    }


def perm_granger_rev(c, d, cn, dn):
    xo, yo = orient(c, cn), orient(d, dn)
    res = permutation_granger_test(yo, xo, max_lag=MAX_LAG,
                                   n_perm=N_PERM, seed=SEED, difference=True)
    return {
        "method": "perm_granger_rev",
        "f_stat": round(float(res["f_stat"]), 4),
        "p_value": round(float(res["p_value"]), 4),
        "significant": bool(res["significant"]),
    }


from scipy import stats as scipy_stats
stats_pearsonr = scipy_stats.pearsonr


def main():
    with open(DATA_PATH) as f:
        metrics_list = json.load(f)

    n_gens = len(metrics_list)
    print(f"Loaded {n_gens} generations from C4 experiment")
    print(f"Parameters: max_lag={MAX_LAG}, n_perm={N_PERM}, seed={SEED}")
    print()

    # Collapse trajectory
    print("=" * 70)
    print("COLLAPSE TRAJECTORY")
    print("-" * 70)
    all_metrics_names = ["token_entropy", "ece", "perplexity",
                         "distinct_1", "distinct_2", "distinct_3", "mauve"]
    gen0 = metrics_list[0]
    gen10 = metrics_list[-1]
    for m in all_metrics_names:
        v0, v10 = gen0[m], gen10[m]
        drift = (v10 - v0) / abs(v0) * 100 if abs(v0) > 1e-12 else 0
        print(f"  {m:>16s}: gen0={v0:.6f}  gen10={v10:.6f}  drift={drift:+.1f}%")
    print()

    # Run all 6 methods on 8 pairs
    METHODS = {
        "naive_pearson": naive_pearson,
        "diff_xcorr": diff_xcorr,
        "threshold_onset": threshold_lead,
        "perm_granger_fwd": perm_granger_fwd,
        "perm_granger_rev": perm_granger_rev,
        "toda_yamamoto": toda_yamamoto,
    }

    results = {}
    all_p = []
    p_keys = []

    for cn in CANARY:
        for dn in DOWNSTREAM:
            pair_key = f"{cn}->{dn}"
            c = extract(metrics_list, cn)
            d = extract(metrics_list, dn)

            pair_res = {}
            for mname, mfn in METHODS.items():
                try:
                    r = mfn(c, d, cn, dn)
                except Exception as e:
                    r = {"method": mname, "error": str(e), "significant": False}
                pair_res[mname] = r

                pv = r.get("p_value")
                if pv is not None and mname != "threshold_onset":
                    all_p.append(pv)
                    p_keys.append((pair_key, mname))

            results[pair_key] = pair_res

    # BH FDR correction
    if all_p:
        _, fdr_ps, _, _ = multipletests(all_p, method="fdr_bh")
        for i, (pk, mn) in enumerate(p_keys):
            results[pk][mn]["p_fdr"] = round(float(fdr_ps[i]), 6)
            results[pk][mn]["sig_fdr"] = bool(fdr_ps[i] < FDR_Q)

    # Print per-pair detail table
    print("=" * 70)
    print("PER-PAIR DETAIL (8 canonical pairs × 6 methods)")
    print("-" * 70)
    method_short = {
        "naive_pearson": "Naive",
        "diff_xcorr": "Diff",
        "threshold_onset": "Thresh",
        "perm_granger_fwd": "PG_fwd",
        "perm_granger_rev": "PG_rev",
        "toda_yamamoto": "TY",
    }
    morder = ["naive_pearson", "diff_xcorr", "threshold_onset",
              "perm_granger_fwd", "perm_granger_rev", "toda_yamamoto"]

    hdr = f"{'Pair':<28s}"
    for mn in morder:
        hdr += f" {method_short[mn]:>7s}"
    hdr += "  votes"
    print(hdr)
    print("-" * 80)

    method_sig_counts = {mn: 0 for mn in morder}
    pair_votes = {}

    for cn in CANARY:
        for dn in DOWNSTREAM:
            pk = f"{cn}->{dn}"
            pr = results[pk]
            row = f"{pk:<28s}"
            votes = 0
            for mn in morder:
                r = pr[mn]
                if mn == "threshold_onset":
                    sig = r.get("significant", False)
                elif mn in ("diff_xcorr", "perm_granger_fwd", "perm_granger_rev"):
                    sig = r.get("sig_fdr", r.get("significant", False))
                elif mn == "toda_yamamoto":
                    sig = r.get("sig_fdr", r.get("significant", False))
                else:
                    sig = r.get("significant", False)

                mark = "Y" if sig else "N"
                if "error" in r:
                    mark = "E"
                row += f" {mark:>7s}"
                if sig:
                    votes += 1
                    method_sig_counts[mn] += 1
            row += f"  {votes}/6"
            print(row)
            pair_votes[pk] = votes

    # Summary table
    print()
    print("=" * 70)
    print("METHOD SUMMARY (Table 5 Row)")
    print("-" * 70)
    print(f"{'Method':<28s} {'Sig/8':>6s}  Pairs")
    print("-" * 60)

    for mn in morder:
        sig_pairs = []
        for cn in CANARY:
            for dn in DOWNSTREAM:
                pk = f"{cn}->{dn}"
                r = results[pk][mn]
                if mn == "threshold_onset":
                    sig = r.get("significant", False)
                elif mn in ("diff_xcorr", "perm_granger_fwd", "perm_granger_rev", "toda_yamamoto"):
                    sig = r.get("sig_fdr", r.get("significant", False))
                else:
                    sig = r.get("significant", False)
                if sig:
                    sig_pairs.append(pk)
        cnt = len(sig_pairs)
        pairs_str = ", ".join(sig_pairs) if sig_pairs else "none"
        label = method_short[mn]
        print(f"{label:<28s} {cnt}/8     {pairs_str}")

    # Consensus
    for thresh in [3, 4, 5]:
        cnt = sum(1 for v in pair_votes.values() if v >= thresh)
        pairs = [pk for pk, v in pair_votes.items() if v >= thresh]
        pairs_str = ", ".join(pairs) if pairs else "none"
        print(f"{'Consensus >=' + str(thresh) + '/6':<28s} {cnt}/8     {pairs_str}")

    # Detailed per-pair results
    print()
    print("=" * 70)
    print("DETAILED RESULTS")
    print("-" * 70)
    for cn in CANARY:
        for dn in DOWNSTREAM:
            pk = f"{cn}->{dn}"
            pr = results[pk]
            print(f"\n  {pk}:")
            for mn in morder:
                r = pr[mn]
                if "error" in r:
                    print(f"    {method_short[mn]:>8s}: ERROR - {r['error']}")
                    continue
                parts = []
                if "r" in r:
                    parts.append(f"r={r['r']:.4f}")
                if "lag" in r:
                    parts.append(f"lag={r['lag']}")
                if "lead_time" in r:
                    parts.append(f"lead={r['lead_time']}")
                if "canary_onset" in r:
                    parts.append(f"c_onset={r['canary_onset']}")
                if "downstream_onset" in r:
                    parts.append(f"d_onset={r['downstream_onset']}")
                if "f_stat" in r:
                    parts.append(f"F={r['f_stat']:.4f}")
                if "wald_F" in r and r["wald_F"] is not None:
                    parts.append(f"F={r['wald_F']:.4f}")
                if "p_value" in r and r["p_value"] is not None:
                    parts.append(f"p={r['p_value']:.4f}")
                if "p_fdr" in r:
                    parts.append(f"p_fdr={r['p_fdr']:.4f}")
                if "d_max" in r:
                    parts.append(f"d_max={r['d_max']}")
                if "df_resid" in r:
                    parts.append(f"df_resid={r['df_resid']}")
                sig = r.get("sig_fdr", r.get("significant", False))
                sig_str = "SIG" if sig else "n.s."
                detail = ", ".join(parts)
                print(f"    {method_short[mn]:>8s}: {sig_str:4s} | {detail}")

    # Save JSON
    os.makedirs(OUT_DIR, exist_ok=True)
    output = {
        "experiment": "pythia1b_c4_a100_s42",
        "model": "pythia-1b",
        "dataset": "c4",
        "alpha": 1.0,
        "seed": 42,
        "n_generations": n_gens,
        "canonical_pairs": [f"{cn}->{dn}" for cn in CANARY for dn in DOWNSTREAM],
        "methods": list(method_short.values()),
        "parameters": {
            "max_lag": MAX_LAG, "n_perm": N_PERM, "seed": SEED, "fdr_q": FDR_Q,
        },
        "trajectory": {m: {"gen0": gen0[m], "gen10": gen10[m],
                          "drift_pct": round((gen10[m] - gen0[m]) / abs(gen0[m]) * 100, 2)
                          if abs(gen0[m]) > 1e-12 else 0.0}
                       for m in all_metrics_names},
        "per_pair": results,
        "pair_votes": pair_votes,
        "method_sig_counts": {method_short[mn]: method_sig_counts[mn] for mn in morder},
    }

    class NE(json.JSONEncoder):
        def default(self, o):
            if isinstance(o, (np.integer,)): return int(o)
            if isinstance(o, (np.floating,)): return float(o)
            if isinstance(o, np.ndarray): return o.tolist()
            if isinstance(o, np.bool_): return bool(o)
            return super().default(o)

    out_path = os.path.join(OUT_DIR, "c4_8pair_6method_analysis.json")
    with open(out_path, "w") as f:
        json.dump(output, f, indent=2, cls=NE)
    print(f"\nSaved: {out_path}")


if __name__ == "__main__":
    main()
PYEOF
